import{_ as l,C as c,o as i,c as h,j as d,a,E as e,ak as r}from"./chunks/framework.DxrHb2fb.js";const g=JSON.parse('{"title":"MarkdownStream 流式正文","description":"","frontmatter":{},"headers":[],"relativePath":"components/markdown-stream.md","filePath":"components/markdown-stream.md","lastUpdated":1790400917000}'),s={name:"components/markdown-stream.md"},m={id:"markdownstream-流式正文",tabindex:"-1"};function k(b,t,u,p,f,w){const n=c("Badge"),o=c("XhDemo");return i(),h("div",null,[d("h1",m,[t[0]||(t[0]=a("MarkdownStream 流式正文 ",-1)),e(n,{type:"info",text:"alpha"}),t[1]||(t[1]=a()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#markdownstream-流式正文","aria-label":'Permalink to "MarkdownStream 流式正文 <Badge type="info" text="alpha" />"'},"​",-1))]),t[3]||(t[3]=r('<p>把已渲染的 Markdown 块列表投影为带稳定 key 的正文结构，按块的种类分流。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/markdown-stream" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/markdown-stream.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/markdown-stream" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/markdown-stream" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/markdown-stream.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>块列表由宿主用流式渲染器得到，组件只按 key 铺开、按种类分流</p>',4)),e(o,{src:"markdown-stream/01-basic"}),t[4]||(t[4]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;markdown-stream&quot;</code>：<strong><code>root</code></strong> · <strong><code>content</code></strong> · <code>block</code> · <code>live-region</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="流式增长" tabindex="-1">流式增长 <a class="header-anchor" href="#流式增长" aria-label="Permalink to &quot;流式增长&quot;">​</a></h3><p>只有生长中的块每帧重渲，定型的块 key 不变、节点原地保留，选区与滚动位置才能保持</p>',6)),e(o,{src:"markdown-stream/02-streaming"}),t[5]||(t[5]=d("h3",{id:"代码块交给代码视图",tabindex:"-1"},[a("代码块交给代码视图 "),d("a",{class:"header-anchor",href:"#代码块交给代码视图","aria-label":'Permalink to "代码块交给代码视图"'},"​")],-1)),t[6]||(t[6]=d("p",null,"markdown 块铺设 html，代码块取 source 交出：按 html 渲染会使同一段代码出现两次",-1)),e(o,{src:"markdown-stream/03-code-blocks"}),t[7]||(t[7]=d("h3",{id:"流式光标",tabindex:"-1"},[a("流式光标 "),d("a",{class:"header-anchor",href:"#流式光标","aria-label":'Permalink to "流式光标"'},"​")],-1)),t[8]||(t[8]=d("p",null,"尚未收到任何块时光标就已存在，caret 设为 false 可以整个关闭",-1)),e(o,{src:"markdown-stream/04-caret"}),t[9]||(t[9]=d("h3",{id:"尺寸",tabindex:"-1"},[a("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[10]||(t[10]=d("p",null,"size 改变正文字号与块间距，三档共用同一份块列表",-1)),e(o,{src:"markdown-stream/05-size"}),t[11]||(t[11]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>展示 AI 回复的正文，且正文边生成边显示。</li><li>正文中混有代码块与公式，需要分别交给专门的组件渲染。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>正文是一次性获取的静态文档时，直接渲染，不经过流式内核。</li><li>只是一段纯文本时，使用<a href="./typography">排印</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>组件不解析 Markdown，也不持有渲染器。块列表由宿主调用 <code>@xihan-ui/markdown</code> 的 <code>createStreamRenderer().render(全文)</code> 得到后传入；渲染器有状态，由持有方负责。</li><li>块的 <code>key</code> 稳定：生长中的块 key 不变，定型的块 key 不再变化。框架据此复用同一份 DOM 只更新文本；每收到一个字就重建节点会丢失选区与滚动位置。</li><li><code>html</code> 只对 markdown 块有效。代码块取 <code>source</code> 交给<a href="./code-view">代码视图</a>，公式块取 <code>source</code> 交给宿主选择的公式引擎；不接管时的降级结果是把原文作为正文显示。</li><li>流式光标是皮肤的 <code>::after</code>，不做成组件。它绘制在带 <code>data-caret</code> 的部件上：正文增长时是生长中的块，尚无任何块时是外壳，因此请求刚发出、尚无内容时页面上也有反馈。<code>caret</code> 设为 <code>false</code> 时两处都不发该属性。</li><li>光标在等待第一个字时闪烁，出字后停为实心：正文本身在变化，继续闪烁只是噪声。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>代码块交给<a href="./code-view">代码视图</a>，整段正文放入<a href="./message-feed">消息流</a>的一条消息。</li><li>逐字输出的节奏由使用者驱动：<code>@xihan-ui/chat-stream</code> 的 <code>visibleLength</code> 是纯函数，时间原点与 rAF 循环由持有方编写。</li><li>正文中需要嵌入行内来源角标、脚注等节点时，用 <code>block</code> 插槽接管该块自行渲染。组件不向已消毒的 html 中插入节点，这个插槽就是为此保留的位置。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>块列表整份传入，不在外部切片：稳定 key 依赖整份列表的下标与内容。</li><li>交出代码块时一并传递 <code>complete</code>，代码组件据此决定是否着色。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>每帧新建渲染器：缓存失效，长回复后段会明显卡顿。</li><li>同时渲染代码块的 <code>html</code> 与交给代码组件的内容：同一段代码会出现两次。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-markdown-stream&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhMarkdownStreamContent</code> <code>XhMarkdownStreamLiveRegion</code> <code>XhMarkdownStreamRoot</code></td></tr><tr><td>组合式函数</td><td><code>useMarkdownStream</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/markdown-stream.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>announce</code></td><td><code>&#39;off&#39; | &#39;polite&#39; | &#39;assertive&#39;</code></td><td></td><td>播报档位，默认 off：会话级播报区在消息流层，不在每条回复中各开一个。</td></tr><tr><td><code>blocks</code></td><td><code>readonly MarkdownBlock[]</code></td><td>是</td><td>已渲染完成的块列表。</td></tr><tr><td><code>caret</code></td><td><code>boolean</code></td><td></td><td>是否绘制流式光标，默认绘制。设为 false 时不发出任何 data-caret。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>streaming</code></td><td><code>boolean</code></td><td></td><td>该段正文是否仍在增长，只写 data-streaming。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;MarkdownStreamTranslations&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="markdownblock" tabindex="-1">MarkdownBlock <a class="header-anchor" href="#markdownblock" aria-label="Permalink to &quot;MarkdownBlock&quot;">​</a></h3><p><code>blocks</code> 的元素。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>key</code></td><td><code>string</code></td><td>是</td><td>稳定 key。生长中的块恒为 {@link MARKDOWN_STREAM_LIVE_KEY}。</td></tr><tr><td><code>kind</code></td><td><code>&#39;markdown&#39; | &#39;code&#39; | &#39;math&#39; | &#39;html&#39;</code></td><td>是</td><td></td></tr><tr><td><code>html</code></td><td><code>string</code></td><td>是</td><td>已消毒的 HTML。只对 kind 为 markdown 的块有效，见 {@link markdownBlockHtml}。</td></tr><tr><td><code>complete</code></td><td><code>boolean</code></td><td>是</td><td>该块是否已闭合。</td></tr><tr><td><code>lang</code></td><td><code>string</code></td><td></td><td>围栏语言标注，仅 code 块有。</td></tr><tr><td><code>source</code></td><td><code>string</code></td><td></td><td>块正文原文，仅 code 与 math 块有。</td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhMarkdownStreamContent</code></td><td><code>block</code></td><td><code>MarkdownStreamBlockSlotProps</code></td><td></td></tr><tr><td><code>XhMarkdownStreamRoot</code></td><td><code>default</code></td><td><code>MarkdownStreamRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhMarkdownStreamContent</code></td><td><code>children</code></td><td><code>SlotChildren&lt;MarkdownStreamBlockSlotProps&gt;</code></td><td></td><td>逐块接管该块的正文；未提供时按块类型铺设。</td></tr><tr><td><code>XhMarkdownStreamRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;MarkdownStreamRootSlotProps&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;streaming&#39; | &#39;complete&#39;</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>blocks</code></td><td><code>readonly MarkdownBlock[]</code></td><td></td></tr><tr><td><code>streaming</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>announcement</code></td><td><code>string | undefined</code></td><td>播报文本；announce 为 off、或正文仍在增长时为 undefined。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBlockProps</code></td><td><code>(props: { block: MarkdownBlock }) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/WCAG21/Techniques/general/G202" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td></td><td>任何时候</td><td>组件不接管任何按键；块内的链接、代码块各自的停靠点由它们自己提供</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>&#39;assertive&#39; | &#39;polite&#39;</td></tr><tr><td><code>live-region</code></td><td><code>role</code></td><td>&#39;alert&#39; | &#39;status&#39;</td></tr></tbody></table><ul><li>正文不加 role，也不做成活动区域：每个 token 播报一次会淹没读屏。</li><li>需要在一段回复完成时播报一句，把 <code>announce</code> 设为 <code>polite</code> 并渲染播报区。一个会话中只应有一个活动区域，多个会互相打断。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/markdown-stream.css</code> 使用 <code>[data-scope=&quot;markdown-stream&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 与 <code>xihan.motion</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-caret</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;streaming&#39; | &#39;complete&#39;</td></tr><tr><td><code>block</code></td><td><code>data-caret</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>block</code></td><td><code>data-complete</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>block</code></td><td><code>data-kind</code></td><td>block.kind</td></tr><tr><td><code>block</code></td><td><code>data-lang</code></td><td>block.lang</td></tr><tr><td><code>block</code></td><td><code>data-live</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-markdown-stream-caret-bg</code></td><td><code>block</code><br><code>root</code></td><td><code>background</code></td><td><code>caret</code></td><td><code>--xh-fg-default</code></td><td>markdown-stream 的 block、root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-duration</code></td><td><code>root</code></td><td><code>animation</code></td><td><code>caret</code></td><td><code>--xh-motion-loop-caret</code></td><td>markdown-stream 的 root 部件 animation 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-enter-duration</code></td><td><code>block</code></td><td><code>animation</code></td><td><code>caret</code></td><td><code>--xh-motion-duration-enter</code></td><td>markdown-stream 的 block 部件 animation 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-gap</code></td><td><code>block</code><br><code>root</code></td><td><code>margin-inline-start</code></td><td><code>caret</code></td><td><code>0.1em</code></td><td>markdown-stream 的 block、root 部件 margin-inline-start 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-h</code></td><td><code>block</code><br><code>root</code></td><td><code>block-size</code></td><td><code>caret</code></td><td><code>1.05em</code></td><td>markdown-stream 的 block、root 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-radius</code></td><td><code>block</code><br><code>root</code></td><td><code>border-radius</code></td><td><code>caret</code></td><td><code>--xh-shape-inset</code></td><td>markdown-stream 的 block、root 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-shift</code></td><td><code>block</code><br><code>root</code></td><td><code>translate</code></td><td><code>caret</code></td><td><code>-0.5px</code></td><td>markdown-stream 的 block、root 部件 translate 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-w</code></td><td><code>block</code><br><code>root</code></td><td><code>inline-size</code></td><td><code>caret</code></td><td><code>--xh-stroke-thick</code></td><td>markdown-stream 的 block、root 部件 inline-size 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>markdown-stream 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-font-size</code></td><td><code>root</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_markdown-stream-font-size</code></td><td>markdown-stream 的 root 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-gap</code></td><td><code>content</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_markdown-stream-gap</code></td><td>markdown-stream 的 content 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-leading</code></td><td><code>root</code></td><td><code>line-height</code></td><td><code>default</code></td><td><code>--xh-text-prose-leading</code></td><td>markdown-stream 的 root 部件 line-height 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-mono</code></td><td><code>block</code></td><td><code>font-family</code></td><td><code>kind=code</code><br><code>kind=math</code></td><td><code>--xh-font-family-mono</code></td><td>markdown-stream 的 block 部件 font-family 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：出现 · 循环（见<a href="./../design/motion#角色">动效规范</a>）。</p><p>可覆盖的动效槽：<code>--xh-markdown-stream-caret-duration</code> · <code>--xh-markdown-stream-caret-enter-duration</code>。</p><p>关键帧 <code>xh-markdown-stream-caret</code> · <code>xh-markdown-stream-caret-in</code> 随皮肤自带，不引用别处文件里的名字。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',57))])}const q=l(s,[["render",k]]);export{g as __pageData,q as default};
